def check_occurences(test_list):
    """Write a function to check the occurrences of records which occur similar times in the given tuples.

    Records that contain the same elements in a different order
    (e.g. ``(3, 1)`` and ``(1, 3)``) are considered the same record.
    Each record is canonicalised by sorting its elements, and the
    returned dict maps that canonical tuple to its occurrence count.
    """
    counts = {}
    for record in test_list:
        try:
            key = tuple(sorted(record))
        except TypeError:
            # Elements of mixed/incomparable types: use a deterministic
            # ordering so permutations still map to the same key.
            key = tuple(sorted(record, key=repr))
        counts[key] = counts.get(key, 0) + 1
    return counts
